/**
 * A retailer's current REGULAR price for one SKU, not a promotion.
 *
 * Keyed on the retailer's own SKU (`shelf_id`), which often has no
 * promotion and therefore no `product_id`. `ean` is the cross-retailer join
 * key where the retailer publishes one; Aldi, Ekoplaza and Hoogvliet do not.
 */
export interface ShelfPriceItem {
  /** Retailer slug */
  retailer: string;
  /** The retailer's own SKU identifier */
  shelf_id: string;
  /** EAN/GTIN, when the retailer publishes one */
  ean?: string | null;
  /** Product name as the retailer states it */
  name: string;
  /** Brand, when stated */
  brand?: string | null;
  /** Product image. Published by PLUS, Ekoplaza, Colruyt and Delhaize; null for the other chains. */
  image_url?: string | null;
  /** Current regular (non-promotional) price */
  price: number;
  /** ISO currency code */
  currency?: string;
  /** Pack size as stated by the retailer */
  quantity?: string | null;
  /** Unit of unit_price: kg, L or stuk. Null when no comparable unit exists, e.g. one price over several pack sizes */
  unit?: string | null;
  /** Derived price per standard unit (kg/L/piece) */
  unit_price?: number | null;
  /** Nutri-Score grade a-e (lowercase), where the retailer publishes one: Albert Heijn (NL and BE), Colruyt, Bio-Planet and Delhaize. Null for every other chain, and null where the chain itself states no grade -- a brand that refuses the Nutri-Score is published as null, never as a grade. */
  nutriscore?: string | null;
  /** Link to the product on the retailer's own site */
  product_url?: string | null;
  /** When this price last actually changed (not a snapshot timestamp). ISO 8601 with the Dutch UTC offset. */
  price_changed_at?: string | null;
  /** When we last observed this row at the retailer -- the freshness indicator, what `extracted_at` is on a promotion. ISO 8601 with the Dutch UTC offset. */
  last_seen: string | null;
}
